import json
with open('/home/ubuntu/.agent-ml-research-prod_0510/projects/causal_annot_error_attrib/artifacts/ppi_empirical_validation.json') as f:
    data = json.load(f)

print('=== META ===')
print(json.dumps(data['meta'], indent=2))

print('\n=== GRAND SUMMARY ===')
gs = data['grand_summary']
for topo in ['confounding','mediation','collider','exposure','mbias','iv','frontdoor']:
    if topo in gs:
        print(f'\n{topo}:')
        for method in ['ppi','naive_plugin','dsl','mcsimex','mla']:
            if method in gs[topo]:
                v = gs[topo][method]
                if isinstance(v, dict):
                    print(f'  {method}: mean_red={v.get(\"mean_bias_reduction\",\"?\")} ci={v.get(\"ci_95\",\"?\")}')
                elif v is None:
                    print(f'  {method}: None')
                else:
                    print(f'  {method}: {v}')
